import React, { useState, useEffect } from "react";
import categoryProductService from "../../services/categoryProductService";
import "./CategoryProductList.css";
const CategoryProductList = () => {
    const [categoryProducts, setCategoryProducts] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchCategoryProducts = async () => {
            try {
                const data = await categoryProductService.getAllCategoryProducts();
                setCategoryProducts(data);
            } catch (error) {
                console.error("Lỗi khi tải danh mục sản phẩm:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchCategoryProducts();
    }, []);

    // Hàm nhỏ giúp tự động hiển thị Icon phù hợp với tên danh mục cho "đúng bài"
    const getIconCategory = (name) => {
        const lowerName = name?.toLowerCase() || "";
        if (lowerName.includes("điện thoại") || lowerName.includes("iphone")) return "fa-mobile-screen-button";
        if (lowerName.includes("máy tính bảng") || lowerName.includes("ipad")) return "fa-tablet-screen-button";
        if (lowerName.includes("laptop") || lowerName.includes("máy tính")) return "fa-laptop";
        if (lowerName.includes("tai nghe")) return "fa-headphones";
        if (lowerName.includes("sofa") || lowerName.includes("ghế")) return "fa-couch";
        if (lowerName.includes("bàn")) return "fa-table";
        if (lowerName.includes("giường")) return "fa-bed";
        return "fa-box-open"; // Icon mặc định nếu không khớp từ khóa
    };

    if (loading) {
        return (
            <div className="d-flex justify-content-center py-4">
                <div className="spinner-border spinner-border-sm text-secondary" role="status">
                    <span className="visually-hidden">Đang tải danh mục...</span>
                </div>
                <span className="ms-2 text-muted small">Đang tải danh mục...</span>
            </div>
        );
    }

    return (
        /* - flex-nowrap: Ép các phần tử không được phép xuống hàng.
          - overflow-x-auto: Bật tính năng cuộn ngang nếu bị tràn màn hình.
          - pb-2: Thêm chút padding bottom để thanh scrollbar (nếu xuất hiện) không đè vào chữ.
          - hide-scrollbar: Class CSS tùy chỉnh giúp ẩn thanh cuộn thô kệch đi cho đẹp.
        */
        <div className="d-flex flex-nowrap overflow-x-auto justify-content-start justify-content-lg-center gap-3 pb-2 hide-scrollbar">
            {categoryProducts.map((item) => (
                /* Thay vì dùng col, ta dùng flex-shrink-0 để các card giữ nguyên kích thước,
                  và đặt chiều rộng cố định (width) cho từng card là 160px để tụi nó đều tăm tắp.
                */
                <div key={item.id} className="flex-shrink-0" style={{ width: "160px" }}>
                    <div className="modern-category-card p-3 text-center h-100 bg-white rounded-3 border-0 shadow-sm d-flex flex-column align-items-center justify-content-center">

                        {/* Khung Icon tròn */}
                        <div
                            className="category-icon-wrapper d-flex align-items-center justify-content-center rounded-circle mb-2"
                            style={{ width: "55px", height: "55px", backgroundColor: "#f8f9fa", color: "#495057" }}
                        >
                            <i className={`fa-solid ${getIconCategory(item.name)} fs-4`}></i>
                        </div>

                        {/* Nội dung chữ */}
                        <div className="category-text mt-1 w-100">
                            <h6 className="fw-semibold text-dark mb-1 text-truncate" style={{ fontSize: "0.85rem" }}>
                                {item.name}
                            </h6>
                            <span className="text-muted d-block" style={{ fontSize: "0.75rem" }}>
                                Xem ngay <i className="fa-solid fa-chevron-right ms-1" style={{ fontSize: "0.6rem" }}></i>
                            </span>
                        </div>

                    </div>
                </div>
            ))}
        </div>
    );
};

export default CategoryProductList;
